SELECT *
FROM sys_warn
WHERE deleted = 0


    AND warn_no LIKE CONCAT('%', #{warnNo}, '%')



    AND facility_id = #{facilityId}



    AND facility_name LIKE CONCAT('%', #{facilityName}, '%')



    AND facility_code = #{facilityCode}



    AND work_order_id = #{workOrderId}



    AND work_order_code = #{workOrderCode}



    AND device_id = #{deviceId}



    AND device_code = #{deviceCode}



    AND monitor_id = #{monitorId}



    AND monitor_code = #{monitorCode}



    AND status = #{status}



    AND assign_status = #{assignStatus}



    AND facility_type = #{facilityType}



    AND type = #{type}



    AND over_index = #{overIndex}



    AND way_type = #{wayType}



    AND level = #{level}



    AND trigger_time BETWEEN #{triggerTime[0]} AND #{triggerTime[1]}



    AND create_time BETWEEN #{createTime[0]} AND #{createTime[1]}


ORDER BY update_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(1)
FROM sys_warn
WHERE deleted = 0


    AND warn_no LIKE CONCAT('%', #{warnNo}, '%')



    AND facility_id = #{facilityId}



    AND facility_name LIKE CONCAT('%', #{facilityName}, '%')



    AND facility_code = #{facilityCode}



    AND work_order_id = #{workOrderId}



    AND work_order_code = #{workOrderCode}



    AND device_id = #{deviceId}



    AND device_code = #{deviceCode}



    AND monitor_id = #{monitorId}



    AND monitor_code = #{monitorCode}



    AND status = #{status}



    AND assign_status = #{assignStatus}



    AND facility_type = #{facilityType}



    AND type = #{type}



    AND over_index = #{overIndex}



    AND way_type = #{wayType}



    AND level = #{level}



    AND trigger_time BETWEEN #{triggerTime[0]} AND #{triggerTime[1]}



    AND create_time BETWEEN #{createTime[0]} AND #{createTime[1]}

SELECT w.id AS warnId, w.facility_id AS coverId, c.cover_no AS coverCode, CONCAT(c.cover_no, '号井盖') AS coverName, c.area_code AS areaId, '' AS areaName, CAST(w.type AS UNSIGNED) AS warnType, CASE CAST(w.type AS UNSIGNED) WHEN 0 THEN '倾斜超标' WHEN 1 THEN '位移超标' WHEN 2 THEN '水位超标' WHEN 3 THEN '井盖开启超时' WHEN 4 THEN '设备离线' ELSE '未知' END AS warnTypeName, w.level AS warnLevel, CASE w.level WHEN 0 THEN '一般' WHEN 1 THEN '重要' WHEN 2 THEN '紧急' ELSE '未知' END AS warnLevelName, IFNULL(w.over_value, '') AS warnValue, IFNULL(w.threshold_value, '') AS thresholdValue, DATE_FORMAT(w.trigger_time, '%Y-%m-%d %H:%i:%s') AS warnTime, CAST(w.assign_status AS UNSIGNED) AS warnStatus, CASE CAST(w.assign_status AS UNSIGNED) WHEN 0 THEN '未处理' WHEN 1 THEN '处理中' WHEN 2 THEN '已解决' WHEN 3 THEN '已忽略' ELSE '未知' END AS warnStatusName, '' AS handleUserId, '' AS handleUserName, w.tenant_id AS tenantId FROM sys_warn w LEFT JOIN manhole_cover c ON w.facility_id = c.id WHERE w.deleted = 0 AND w.tenant_id = #{reqVO.tenantId}
AND w.facility_id = #{reqVO.coverId}
AND w.type = #{reqVO.warnType}
AND w.assign_status = #{reqVO.warnStatus}
AND w.trigger_time >= #{reqVO.warnTimeStart}
AND w.trigger_time <= #{reqVO.warnTimeEnd}
ORDER BY w.trigger_time DESC

SELECT COUNT(*)
FROM sys_warn w
LEFT JOIN manhole_cover c ON w.facility_id = c.id
WHERE w.deleted = 0
AND w.tenant_id = #{tenantId}


    AND w.facility_id = #{coverId}


    AND w.type = #{warnType}


    AND w.assign_status = #{warnStatus}


    AND w.trigger_time >= #{warnTimeStart}


    AND w.trigger_time <= #{warnTimeEnd}
